import{_ as t,o as i,c as a,a6 as s}from"./chunks/framework.DRfakdJW.js";const u=JSON.parse('{"title":"Installation Info","description":"","frontmatter":{},"headers":[],"relativePath":"install_tips.md","filePath":"install_tips.md","lastUpdated":null}'),o={name:"install_tips.md"};function n(l,e,r,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="Installation-Info" tabindex="-1">Installation Info <a class="header-anchor" href="#Installation-Info" aria-label="Permalink to &quot;Installation Info {#Installation-Info}&quot;">​</a></h1><h2 id="ROCm-libraries" tabindex="-1">ROCm libraries <a class="header-anchor" href="#ROCm-libraries" aria-label="Permalink to &quot;ROCm libraries {#ROCm-libraries}&quot;">​</a></h2><p>By default, AMDGPU.jl ships the ROCm runtime (HIP and HSA) and the vendor libraries (rocBLAS, rocSPARSE, rocSOLVER, rocRAND, rocFFT, MIOpen) as lazy artifacts through the <code>ROCm_Runtime</code> subpackage, which downloads AMD&#39;s TheRock distribution tarball matching the GPUs detected on the host. <code>ld.lld</code> and the device bitcode libraries always come from <code>AMDGPU_LLVM_Backend_jll</code> and <code>ROCmDeviceLibs_jll</code>. No system-wide ROCm installation is needed in this mode.</p><p>To use a local ROCm installation instead, set the <code>local</code> preference in the active project and restart Julia:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AMDGPU</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_rocm_version!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(local_rocm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The library locations are then discovered through the <code>ROCm_Runtime_Discovery</code> package, as described below. Use <code>AMDGPU.reset_rocm_version!()</code> to go back to the default artifact-based setup.</p><h3 id="Selecting-the-provider-without-loading-AMDGPU.jl" tabindex="-1">Selecting the provider without loading AMDGPU.jl <a class="header-anchor" href="#Selecting-the-provider-without-loading-AMDGPU.jl" aria-label="Permalink to &quot;Selecting the provider without loading AMDGPU.jl {#Selecting-the-provider-without-loading-AMDGPU.jl}&quot;">​</a></h3><p><code>local</code> is a compile-time preference, and it also gates whether the artifact is <em>resolved</em> at all, so in CI or in a fresh depot it has to be set before <code>Pkg.instantiate()</code> rather than through <code>AMDGPU.set_rocm_version!</code> (which needs AMDGPU.jl loaded first). Write it directly against <code>ROCm_Runtime</code>&#39;s UUID:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Preferences</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_preferences!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">UUID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3129f4d2-de71-4ff3-9833-76037e3ea355&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; force</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>AMDGPU.local_rocm</code> reports which provider was actually selected. Asserting on it is worthwhile in CI, so that a change of default cannot silently swap the ROCm underneath a job.</p><h3 id="When-no-artifact-matches" tabindex="-1">When no artifact matches <a class="header-anchor" href="#When-no-artifact-matches" aria-label="Permalink to &quot;When no artifact matches {#When-no-artifact-matches}&quot;">​</a></h3><p>The artifact is chosen from the GPU architectures detected on the host, which on Linux are read from the <code>/sys/class/kfd/kfd/topology</code> nodes. If nothing is detected — a container without KFD passthrough, a login node, or a host where the <code>amdgpu</code> driver is not loaded — or if the detected architecture is not one of the shipped bundles, then no artifact is downloaded and AMDGPU.jl reports its ROCm components as unavailable.</p><p>There is no fallback path: the provider is decided when AMDGPU.jl is loaded, so an existing system-wide ROCm is only picked up after explicitly opting in with the <code>local</code> preference above.</p><p>The bundles currently shipped are:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Bundle</th><th style="text-align:left;">Platforms</th></tr></thead><tbody><tr><td style="text-align:left;"><code>gfx101x_dgpu</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx103x_all</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx110x_all</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx1150</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx1151</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx1152</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx1153</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx120x_all</code></td><td style="text-align:left;">linux, windows</td></tr><tr><td style="text-align:left;"><code>gfx908</code></td><td style="text-align:left;">linux</td></tr><tr><td style="text-align:left;"><code>gfx90a</code></td><td style="text-align:left;">linux</td></tr><tr><td style="text-align:left;"><code>gfx94x_dcgpu</code></td><td style="text-align:left;">linux</td></tr><tr><td style="text-align:left;"><code>gfx950_dcgpu</code></td><td style="text-align:left;">linux</td></tr></tbody></table><p>To pin the architecture when detection is not possible, for example when preparing a depot on a CPU-only build machine, pass <code>arch</code> a <code>gfx</code> target or a collection of them:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AMDGPU</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_rocm_version!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(arch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gfx942&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>As with <code>local</code>, this writes the <code>arch</code> preference of <code>ROCm_Runtime</code>, so it can equally be set with <code>set_preferences!</code> before AMDGPU.jl is loaded.</p><p>The <code>version</code> preference selects which ROCm distribution the bundle is taken from. Only 7.14 is currently available, so it mainly becomes useful for pinning once more versions ship.</p><h2 id="Local-ROCm-discovery" tabindex="-1">Local ROCm discovery <a class="header-anchor" href="#Local-ROCm-discovery" aria-label="Permalink to &quot;Local ROCm discovery {#Local-ROCm-discovery}&quot;">​</a></h2><p>Everything in this section applies only when the <code>local</code> preference is set. In the default artifact mode the library paths come from the downloaded bundle, and the <code>ROCM_PATH</code>, <code>DEVICE_LIB_PATH</code> and <code>HIP_DEVICE_LIB_PATH</code> environment variables are ignored.</p><p>On Linux, AMDGPU.jl queries the location of ROCm libraries through <code>rocminfo</code> by default. If not successful or on Windows, the following standard directories are searched:</p><p>Standard paths:</p><ul><li><p>Linux: <code>/opt/rocm</code>, <code>/usr</code></p></li><li><p>Windows: <code>C:/Program Files/AMD/ROCm/&lt;rocm-version&gt;</code></p></li></ul><p>If you have non-standard path for ROCm, set <code>ROCM_PATH=&lt;path&gt;</code> environment variable before launching Julia. The <code>AMDGPU.versioninfo()</code> function prints the paths of any libraries found.</p><p>Starting with ROCm 7.14, libraries are installed under a versioned <code>core-&lt;version&gt;</code> subdirectory (for example <code>/opt/rocm/core-7.14/lib</code>) instead of directly in <code>/opt/rocm/lib</code>. AMDGPU.jl handles this automatically by selecting the newest <code>core-*</code> directory found under the ROCm root, so keep <code>ROCM_PATH</code> pointed at the install root (e.g. <code>/opt/rocm</code>) rather than at the versioned subdirectory. A full (&quot;metapackage&quot;) install additionally provides a <code>/opt/rocm/lib</code> compatibility symlink and needs no special handling; the versioned lookup mainly benefits minimal, GPU-architecture-specific installs that omit that symlink.</p><h2 id="GPU-selection-and-architecture-overrides" tabindex="-1">GPU selection and architecture overrides <a class="header-anchor" href="#GPU-selection-and-architecture-overrides" aria-label="Permalink to &quot;GPU selection and architecture overrides {#GPU-selection-and-architecture-overrides}&quot;">​</a></h2><p>These apply in both provider modes, because they are read by the HSA and HIP runtimes themselves rather than by AMDGPU.jl.</p><p>Depending on your GPU model and the functionality you want to use, you may have to force the GPU architecture by setting the <code>HSA_OVERRIDE_GFX_VERSION</code> variable to a compatible version.</p><p>You may also have more than one type of GPU, for example a dedicated AMD GPU and an integrated one. In that case use <code>rocminfo</code> to find which device they are and setting <code>HIP_VISIBLE_DEVICES</code> to the specific device you want to use. Otherwise the runtime may crash if it sees two different architectures.</p><h2 id="Extra-Setup-Details" tabindex="-1">Extra Setup Details <a class="header-anchor" href="#Extra-Setup-Details" aria-label="Permalink to &quot;Extra Setup Details {#Extra-Setup-Details}&quot;">​</a></h2><p>List of additional steps that may be needed to take to ensure everything is working:</p><ul><li><p>Make sure your user is in the same group as <code>/dev/kfd</code>, other than <code>root</code>. For example, it might be the <code>render</code> group: <code>crw-rw---- 1 root render 234, 0 Aug 5 11:43 kfd</code> In this case, you can add yourself to it: <code>sudo usermod -aG render username</code></p></li><li><p>ROCm libraries should be in the standard library locations, or in your <code>LD_LIBRARY_PATH</code>.</p></li><li><p>If you get an error message along the lines of <code>GLIB_CXX_... not found</code>, it&#39;s possible that the C++ runtime used to build the ROCm stack and the one used by Julia are different. If you built the ROCm stack yourself this is very likely the case since Julia normally ships with its own C++ runtime. For more information, check out this <a href="https://github.com/JuliaLang/julia/issues/34276" target="_blank" rel="noreferrer">GitHub issue</a>. A quick fix is to use the <code>LD_PRELOAD</code> environment variable to make Julia use the system C++ runtime library, for example: <code>LD_PRELOAD=/usr/lib/libstdc++.so julia</code> Alternatively, you can build Julia from source as described <a href="https://github.com/JuliaLang/julia/blob/master/doc/build/build.md" target="_blank" rel="noreferrer">here</a>. To quickly debug this issue start Julia and try to load a ROCm library: <code>using Libdl Libdl.dlopen(&quot;/opt/rocm/hsa/lib/libhsa-runtime64.so.1&quot;)</code></p></li></ul><p>Once all of this is setup properly, you should be able to do <code>using AMDGPU</code> successfully.</p><p>See the <a href="/previews/PR1028/tutorials/quickstart#Quick-Start">Quick Start</a> documentation for an introduction to using AMDGPU.jl.</p><h2 id="Preferences" tabindex="-1">Preferences <a class="header-anchor" href="#Preferences" aria-label="Permalink to &quot;Preferences {#Preferences}&quot;">​</a></h2><p>AMDGPU.jl supports setting <a href="https://github.com/JuliaPackaging/Preferences.jl" target="_blank" rel="noreferrer">preferences</a>. Template of <code>LocalPreferences.toml</code> with all options:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AMDGPU</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If \`true\` (default is \`false\`), eagerly run GC to keep the pool from growing too big.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GC is triggered during new allocatoins or synchronization points.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">eager_gc = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use non-blocking synchronization for all \`AMDGPU.synchronize()\` calls (default is \`true\`).</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nonblocking_synchronization = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Memory limit specifies maximum amount of memory in percentages</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a current Julia process can use.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default is &quot;none&quot;, which does not apply any limitation.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hard_memory_limit = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;none&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Notice a space between the value and percentage sign.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hard_memory_limit = &quot;80 %&quot;</span></span></code></pre></div><h2 id="Windows-OS-missing-functionality" tabindex="-1">Windows OS missing functionality <a class="header-anchor" href="#Windows-OS-missing-functionality" aria-label="Permalink to &quot;Windows OS missing functionality {#Windows-OS-missing-functionality}&quot;">​</a></h2><p>Windows <strong>does not</strong> yet support <a href="/previews/PR1028/api/hostcall#Hostcall">Hostcall</a>, which means that some of the functionality does not work, like:</p><ul><li><p>device printing;</p></li><li><p>dynamic memory allocation (from kernels).</p></li></ul><p>These hostcalls are sometimes launched when AMDGPU detects that a kernel might throw an exception, specifically during conversions, like: <code>Int32(1f0)</code>.</p><p>To avoid this, use &#39;unsafe&#39; conversion option: <code>unsafe_trunc(Int32, 1f0)</code>.</p>`,43)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
